def js_object(obj, indent=8):
    raw = json.dumps(obj, ensure_ascii=False, indent=4)
    pad = " " * indent
    return "\n".join(pad + line if line else line for line in raw.split("\n"))

def main():
    with open(INDEX, encoding="utf-8") as f:
        idx = f.read()
    if idx.count(OLD_TS) != 4:
        raise SystemExit(f"expected 4 old timestamps, found {idx.count(OLD_TS)}")
    idx = idx.replace(OLD_TS, TS)
    if idx.count(TS) != 4:
        raise SystemExit(f"expected 4 new timestamps, found {idx.count(TS)}")

    start = idx.find("        const forexData = {")
    end = idx.find("        /* ==========================================\n           B. Market metadata")
    if start < 0 or end < 0:
        raise SystemExit("forexData block markers missing")
    block = "        const forexData = " + json.dumps(DATA, ensure_ascii=False, indent=4) + ";\n\n"
    idx = idx[:start] + block + idx[end:]

    d0 = idx.find("        const dailyChanges = {")
    d1 = idx.find("        const macroDrivers = {")
    if d0 < 0 or d1 < 0:
        raise SystemExit("dailyChanges/macroDrivers missing")
    changes = {
        "EUR/USD": "-0.34%", "USD/JPY": "+0.24%", "AUD/USD": "+0.11%",
        "GBP/USD": "-0.15%", "EUR/JPY": "-0.11%", "GBP/JPY": "+0.09%",
    }
    idx = idx[:d0] + "        const dailyChanges = " + json.dumps(changes, ensure_ascii=False, indent=4) + ";\n\n" + idx[d1:]

    m0 = idx.find("        const macroDrivers = {")
    m1 = idx.find("        /* ==========================================\n           B2. News")
    if m0 < 0 or m1 < 0:
        raise SystemExit("macroDrivers block markers missing")
    idx = idx[:m0] + "        const macroDrivers = " + json.dumps(DRIVERS, ensure_ascii=False, indent=4) + ";\n\n\n" + idx[m1:]

    needle = "            items: [\n"
    at = idx.find(needle)
    if at < 0:
        raise SystemExit("newsData items missing")
    idx = idx[:at + len(needle)] + NEWS_ITEM_JS + idx[at + len(needle):]

    # parse-check forexData the same way the builders do
    s = idx.find("const forexData = {"); s2 = idx.find("{", s)
    e = idx.find("\n};", s) + len("\n};")
    parsed = json.loads(idx[s2:e][:-1].rstrip())
    assert list(parsed) == ["EUR/USD", "USD/JPY", "AUD/USD", "GBP/USD", "EUR/JPY", "GBP/JPY"]
    with open(INDEX, "w", encoding="utf-8", newline="\r\n") as f:
        f.write(idx)
    print("index.html patched")

    with open(LEDGER, encoding="utf-8") as f:
        ledger = json.load(f)
    watching = ledger["watching"]
    assert len(watching) == 1 and watching[0]["pair"] == "EUR/USD" and watching[0]["reportDate"] == "23/10/2026"
    revoked = dict(watching[0])
    revoked["note"] = "revoked in the 27/10 edition, not re-armed: the Oct 26 close 1.1188 and the Oct 27 close 1.1150 never entered 1.1260-1.1300, and 1.1150 is itself the new 9-month low — a stop over the 10-day high 1.1253 puts 1:2 at 1.0920 through four rounds, and the 56-pip floor stop is not structural"
    revoked["outcome"] = "revoked"
    revoked["exitDate"] = "27/10/2026"
    revoked["entryDate"] = None
    revoked["realizedR"] = None
    ledger["closed"].append(revoked)
    ledger["watching"] = []
    # open GBP/USD ticket is not modified
    assert any(t["pair"] == "GBP/USD" and t.get("entryDate") == "22/10/2026" for t in ledger["open"])
    ledger["meta"]["lastUpdated"] = "27/10/2026"
    with open(LEDGER, "w", encoding="utf-8", newline="\n") as f:
        json.dump(ledger, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print("track-record.json patched")

    with open(NEWS, encoding="utf-8") as f:
        news = f.read()
    news = news.replace(
        "Market Wire · Yen Under 157, Shelf Re-armed",
        "Market Wire · Euro Pins the 9-Month Low",
    )
    news = news.replace(
        "Telégrafo da Mesa · Iene Sob 157, Prateleira Rearmada",
        "Telégrafo da Mesa · Euro Crava a Mínima de 9 Meses",
    )
    news = news.replace(OLD_TS, TS)
    old_cal = '''                    <span class="cal-date">≈28/10</span>
                    <span class="cal-event"><span class="lang-en">Australian Q3 CPI</span><span class="lang-pt" style="display:none;">CPI australiano do Q3</span></span>'''
    new_cal = '''                    <span class="cal-date">28/10</span>
                    <span class="cal-event"><span class="lang-en">Australian CPI — 00:30 UTC (ABS)</span><span class="lang-pt" style="display:none;">CPI australiano — 00:30 UTC (ABS)</span></span>'''
    if old_cal not in news:
        raise SystemExit("calendar cell missing")
    news = news.replace(old_cal, new_cal, 1)
    marker = "                <!-- News 23/10/2026:"
    if marker not in news:
        raise SystemExit("news card marker missing")
    news = news.replace(marker, NEWS_CARD + marker, 1)
    if news.count("27/10/2026") < 3:
        raise SystemExit("news.html stamp incomplete")
    with open(NEWS, "w", encoding="utf-8", newline="\n") as f:
        f.write(news)
    print("news.html patched")

    with open(SITEMAP, encoding="utf-8") as f:
        sm = f.read()
    n = sm.count("2026-10-23")
    if n != 9:
        raise SystemExit(f"expected 9 sitemap dates, found {n}")
    sm = sm.replace("2026-10-23", "2026-10-27")
    with open(SITEMAP, "w", encoding="utf-8", newline="\n") as f:
        f.write(sm)
    print("sitemap patched")

    with open(VERIFY, encoding="utf-8") as f:
        v = f.read()
    v = v.replace('TODAY_TS = "23/10/2026 18:10 UTC"', f'TODAY_TS = "{TS}"')
    v = v.replace('TODAY_DATE = "23/10/2026"  # basis session date (report edition: 23/10/2026)',
                  'TODAY_DATE = "27/10/2026"  # basis session date (report edition: 27/10/2026)')
    old_ticker = '''TICKER = [("EUR/USD","-0.11%"),("USD/JPY","-0.16%"),("AUD/USD","+0.15%"),
          ("GBP/USD","-0.06%"),("EUR/JPY","-0.27%"),("GBP/JPY","-0.22%")]'''
    new_ticker = '''TICKER = [("EUR/USD","-0.34%"),("USD/JPY","+0.24%"),("AUD/USD","+0.11%"),
          ("GBP/USD","-0.15%"),("EUR/JPY","-0.11%"),("GBP/JPY","+0.09%")]'''
    if old_ticker not in v:
        raise SystemExit("verify ticker block missing")
    v = v.replace(old_ticker, new_ticker)
    with open(VERIFY, "w", encoding="utf-8", newline="\n") as f:
        f.write(v)
    print("verify_all.py constants patched")

if __name__ == "__main__":
    main()
